function consoleE(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function consoleInitial(string $value): string {
    if(function_exists('mb_substr')&&function_exists('mb_strtoupper'))return mb_strtoupper(mb_substr($value,0,1,'UTF-8'),'UTF-8');
    return strtoupper(substr($value,0,1));
}
function consoleTime(mixed $value,string $format='d/m/Y H:i'): string {
    if(!$value)return '—';
    try { $tz=new DateTimeZone(config('APP_TIMEZONE','America/Sao_Paulo'));return (new DateTimeImmutable((string)$value,new DateTimeZone('UTC')))->setTimezone($tz)->format($format); }
    catch(Throwable $e){return (string)$value;}
}
